Eigen::Isometry3d posQuatToEigenIsometry(double x, double y, double z,
                                         double q_x, double q_y, double q_z,
                                         double q_w) {
  Eigen::Isometry3d pose(Eigen::Isometry3d::Identity());
  Eigen::Quaterniond quat(q_w, q_x, q_y, q_z);
  pose.translate(Eigen::Vector3d(x, y, z));
  pose.rotate(quat);
  return pose;
}

